#!/bin/sh
# Runs once on first start of an empty data volume. One database per service; each login role can only touch its own
# database (PUBLIC connect revoked), so a compromised service cannot read another service's data.
# LOCAL DEV ONLY: passwords come from compose/.env (generated by gen-env.sh), never committed.
#
# pos and delivery use Row Level Security, which only protects tenants when the API's role does NOT own the tables
# (policies are ENABLEd, not FORCEd: the owner must stay exempt for migrations, pg_dump and the SECURITY DEFINER lookups).
# Security review 2026-10-31 finding 3: with one role per database (owner = app) RLS was inert. So these two databases get
# the three-role split of pos-service app/core/db_roles.py:
#   <svc>_owner     NOLOGIN, owns the database, the schema and every object (migrations SET ROLE to it)
#   <svc>_migrator  LOGIN, member of <svc>_owner: used only by the migrate one-shot
#   <svc>_app       LOGIN NOSUPERUSER NOBYPASSRLS, owns nothing: DML on tables through default privileges
# An EXISTING volume is converted by ./rls-role-split.sh (initdb scripts never run again on a non-empty volume).
set -eu
create() { # db role password
  psql -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d postgres <<SQL
CREATE ROLE $2 LOGIN PASSWORD '$3';
CREATE DATABASE $1 OWNER $2;
REVOKE ALL ON DATABASE $1 FROM PUBLIC;
GRANT CONNECT ON DATABASE $1 TO $2;
SQL
}
split() { # db svc app_password migrator_password
  db=$1 o=$2_owner m=$2_migrator a=$2_app
  psql -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d postgres <<SQL
CREATE ROLE $o NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
CREATE ROLE $m LOGIN PASSWORD '$4' NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
CREATE ROLE $a LOGIN PASSWORD '$3' NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
GRANT $o TO $m;
CREATE DATABASE $db OWNER $o;
REVOKE ALL ON DATABASE $db FROM PUBLIC;
GRANT CONNECT ON DATABASE $db TO $m, $a;
SQL
  psql -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$db" <<SQL
ALTER SCHEMA public OWNER TO $o;
GRANT USAGE, CREATE ON SCHEMA public TO $o;
GRANT USAGE ON SCHEMA public TO $a;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
ALTER DEFAULT PRIVILEGES FOR ROLE $o IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO $a;
ALTER DEFAULT PRIVILEGES FOR ROLE $o IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO $a;
ALTER DEFAULT PRIVILEGES FOR ROLE $o IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO $a;
SQL
}
split  pos        pos            "$POS_DB_PASSWORD"      "$POS_MIGRATOR_DB_PASSWORD"
create payments   payments_app   "$PAYMENTS_DB_PASSWORD"
create marketing  marketing_app  "$MARKETING_DB_PASSWORD"
create aggregator aggregator_app "$AGGREGATOR_DB_PASSWORD"
create platform    platform_app   "$PLATFORM_DB_PASSWORD"
split  delivery   delivery       "$DELIVERY_DB_PASSWORD" "$DELIVERY_MIGRATOR_DB_PASSWORD"
